// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Masuk dengan email dan password
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Keluar dan mencabut sesi aktif
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ActivateMfa Mengaktifkan MFA dengan kode pertama dari aplikasi autentikator
	// (POST /api/v1/auth/mfa/activate)
	ActivateMfa(ctx context.Context, request ActivateMfaRequestObject) (ActivateMfaResponseObject, error)
	// SetupMfa Membuat secret TOTP baru untuk didaftarkan di aplikasi autentikator
	// (POST /api/v1/auth/mfa/setup)
	SetupMfa(ctx context.Context, request SetupMfaRequestObject) (SetupMfaResponseObject, error)
	// ChangePassword Mengganti password sendiri
	// (POST /api/v1/auth/password/change)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// RequestPasswordReset Meminta tautan atur ulang password
	// (POST /api/v1/auth/password/forgot)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// SetupPassword Mengatur password dari tautan undangan atau atur ulang
	// (POST /api/v1/auth/password/setup)
	SetupPassword(ctx context.Context, request SetupPasswordRequestObject) (SetupPasswordResponseObject, error)
	// GetPasswordToken Memeriksa tautan undangan atau atur ulang password
	// (GET /api/v1/auth/password/token)
	GetPasswordToken(ctx context.Context, request GetPasswordTokenRequestObject) (GetPasswordTokenResponseObject, error)
	// Reauthenticate Konfirmasi identitas untuk aksi sensitif
	// (POST /api/v1/auth/reauth)
	Reauthenticate(ctx context.Context, request ReauthenticateRequestObject) (ReauthenticateResponseObject, error)
	// RefreshSession Memperbarui access token dengan refresh token (rotasi)
	// (POST /api/v1/auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// GetCurrentUser User yang sedang login beserta permission
	// (GET /api/v1/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// ListPermissions Katalog permission
	// (GET /api/v1/permissions)
	ListPermissions(ctx context.Context, request ListPermissionsRequestObject) (ListPermissionsResponseObject, error)
	// ListRoles Daftar role beserta permission
	// (GET /api/v1/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// SetRolePermissions Mengganti permission role (berlaku langsung, butuh re-autentikasi)
	// (PUT /api/v1/roles/{id}/permissions)
	SetRolePermissions(ctx context.Context, request SetRolePermissionsRequestObject) (SetRolePermissionsResponseObject, error)
	// ListUsers Daftar pengguna
	// (GET /api/v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Membuat pengguna dan mengirim undangan atur password
	// (POST /api/v1/users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// GetUser Detail pengguna
	// (GET /api/v1/users/{id})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// UpdateUser Mengubah nama, divisi, dan role pengguna
	// (PUT /api/v1/users/{id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
	// ActivateUser Mengaktifkan kembali pengguna
	// (POST /api/v1/users/{id}/activate)
	ActivateUser(ctx context.Context, request ActivateUserRequestObject) (ActivateUserResponseObject, error)
	// DeactivateUser Menonaktifkan pengguna dan memutus semua sesinya
	// (POST /api/v1/users/{id}/deactivate)
	DeactivateUser(ctx context.Context, request DeactivateUserRequestObject) (DeactivateUserResponseObject, error)
	// ResendUserInvitation Mengirim ulang undangan atur password
	// (POST /api/v1/users/{id}/resend-invitation)
	ResendUserInvitation(ctx context.Context, request ResendUserInvitationRequestObject) (ResendUserInvitationResponseObject, error)
	// ResetUserMfa Mereset MFA pengguna (HP hilang); pengguna mendaftar ulang saat masuk berikutnya
	// (POST /api/v1/users/{id}/reset-mfa)
	ResetUserMfa(ctx context.Context, request ResetUserMfaRequestObject) (ResetUserMfaResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

